import grpc
import hashlib
import hmac
import time
import importlib
from concurrent import futures
from functools import wraps

# Proto-generated stubs (simplified for demonstration)
class ServiceRequest:
    def __init__(self, service_name="", method_name="", payload=b"", timestamp=0, auth_token=""):
        self.service_name = service_name
        self.method_name = method_name
        self.payload = payload
        self.timestamp = timestamp
        self.auth_token = auth_token

class ServiceResponse:
    def __init__(self, status=0, result=b"", error=""):
        self.status = status
        self.result = result
        self.error = error

# Shared secret for inter-service HMAC authentication
SERVICE_SECRETS = {
    "inventory_service": b"k8s-secret-inv-2024x",
    "billing_service": b"k8s-secret-bil-2024x",
    "analytics_service": b"k8s-secret-ana-2024x",
}

# Registry of allowed service handlers
SERVICE_REGISTRY = {
    "inventory_service": "services.inventory",
    "billing_service": "services.billing",
    "analytics_service": "services.analytics",
}

ALLOWED_METHODS = frozenset([
    "get_stock", "update_stock", "process_payment",
    "generate_report", "get_metrics", "health_check"
])

TIMESTAMP_TOLERANCE = 300  # 5 minutes


def verify_hmac_token(service_name, method_name, payload, timestamp, token):
    """Verify the HMAC token for cross-service authentication."""
    secret = SERVICE_SECRETS.get(service_name)
    if secret is None:
        return False

    message = f"{service_name}:{method_name}:{timestamp}".encode() + payload
    expected = hmac.new(secret, message, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, token)


def check_timestamp_freshness(timestamp):
    """Prevent replay attacks by checking timestamp freshness."""
    current_time = int(time.time())
    return abs(current_time - timestamp) <= TIMESTAMP_TOLERANCE


def validate_method_name(method_name):
    """Validate method name against allowlist."""
    if not method_name.isidentifier():
        return False
    if method_name.startswith('_'):
        return False
    return method_name in ALLOWED_METHODS


def resolve_handler(service_name, method_name):
    """Resolve the appropriate handler for the given service and method."""
    module_path = SERVICE_REGISTRY.get(service_name)
    if module_path is None:
        return None

    # Dynamic resolution with validated inputs
    try:
        module = importlib.import_module(module_path)
        handler = getattr(module, method_name, None)
        return handler
    except (ImportError, AttributeError):
        return None


class GatewayServicer:
    """gRPC Gateway that routes authenticated requests to internal services."""

    def __init__(self):
        self._request_log = []

    def RouteRequest(self, request, context):
        """Main RPC endpoint for cross-service communication."""
        # Step 1: Validate timestamp to prevent replay
        if not check_timestamp_freshness(request.timestamp):
            return ServiceResponse(status=401, error="Request expired")

        # Step 2: Validate service name exists
        if request.service_name not in SERVICE_REGISTRY:
            return ServiceResponse(status=404, error="Service not found")

        # Step 3: Authenticate via HMAC
        if not verify_hmac_token(
            request.service_name, request.method_name,
            request.payload, request.timestamp, request.auth_token
        ):
            return ServiceResponse(status=403, error="Authentication failed")

        # Step 4: Validate method name
        if not validate_method_name(request.method_name):
            return ServiceResponse(status=400, error="Invalid method")

        # Step 5: Resolve and invoke handler
        handler = resolve_handler(request.service_name, request.method_name)
        if handler is None:
            return ServiceResponse(status=404, error="Handler not found")

        try:
            result = handler(request.payload)
            return ServiceResponse(status=200, result=result)
        except Exception as e:
            return ServiceResponse(status=500, error=str(e))

    def RouteInternalDiagnostic(self, request, context):
        """Internal diagnostic endpoint - uses service_name as module path directly
        for flexibility in debugging. Only accessible from authenticated services."""

        if not check_timestamp_freshness(request.timestamp):
            return ServiceResponse(status=401, error="Request expired")

        # Authenticate the calling service
        canonical_name = request.service_name.split(".")[0] + "_service"
        secret = SERVICE_SECRETS.get(canonical_name)
        if secret is None:
            return ServiceResponse(status=403, error="Unknown service")

        message = f"{request.service_name}:{request.method_name}:{request.timestamp}".encode() + request.payload
        expected = hmac.new(secret, message, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected, request.auth_token):
            return ServiceResponse(status=403, error="Authentication failed")

        # For diagnostics, resolve using the full service_name as module path
        try:
            module = importlib.import_module(request.service_name)
            func = getattr(module, request.method_name)
            result = func(request.payload)
            return ServiceResponse(status=200, result=result)
        except Exception as e:
            return ServiceResponse(status=500, error=str(e))


def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    servicer = GatewayServicer()
    # In real code: add_GatewayServicer_to_server(servicer, server)
    server.add_insecure_port('[::]:50051')
    server.start()
    server.wait_for_termination()


if __name__ == '__main__':
    serve()
